# Test the hypothesis: shift = -(row_offset_from_top + 1)

def analyze_demo(demo_data):
    print(f"\nAnalyzing demo with {len(demo_data)} rows:")
    # Find top and bottom rows
    top_r = None
    bottom_r = None
    for r, data in enumerate(demo_data):
        if data['in']:
            if bottom_r is None:
                bottom_r = r
            top_r = r

    # Calculate row offsets and shifts
    for r, data in enumerate(demo_data):
        if data['in']:
            inp = data['in']
            out = data['out']
            row_offset = r - top_r  # rows from top (0, 1, 2, ...)

            if len(inp) == len(out):
                # Calculate shift (if consistent)
                shifts = [o - i for i, o in zip(inp, out)]
                if all(s == shifts[0] for s in shifts):
                    shift = shifts[0]
                    expected_shift = -(row_offset + 1) if row_offset < 2 else 0
                    match = "✓" if shift == expected_shift else "✗"
                    print(f"  Row {r} (offset {row_offset}): {inp} -> {out}, shift={shift} (expected {expected_shift}) {match}")
                else:
                    print(f"  Row {r} (offset {row_offset}): {inp} -> {out}, inconsistent shifts {shifts}")
            elif len(inp) == 1 and len(out) == 1:
                shifts = [out[0] - (inp[0] if row_offset > 0 else inp[0])]
                print(f"  Row {r} (offset {row_offset}): one-to-one {inp} -> {out}, shift={shifts[0] if shifts else 'N/A'}")
            elif len(inp) == 5 and len(out) == 3:
                # Top row special case
                print(f"  Row {r} (offset {row_offset}, top row): {inp} -> {out}, keeps first 3")
            elif len(inp) == 5 and len(out) == 5 and inp == out:
                # Bottom row unchanged
                print(f"  Row {r} (offset {row_offset}, bottom row): unchanged")

